<?php
declare(strict_types=1);
require_once __DIR__.'/includes.php';
$pdo=db(); $error=''; $notice='';
$installed=(int)$pdo->query('SELECT COUNT(*) FROM admins')->fetchColumn()>0;
if(isset($_GET['logout'])){$_SESSION=[];session_destroy();header('Location: admin.php');exit;}
if($_SERVER['REQUEST_METHOD']==='POST'){
 $action=(string)($_POST['action']??'');
 if($action==='setup'){
  csrf_check();
  if($installed){$error='Yönetici hesabı zaten oluşturulmuş.';}
  else{
   $user=trim((string)($_POST['username']??''));$pass=(string)($_POST['password']??'');$pass2=(string)($_POST['password2']??'');
   if(!preg_match('/^[a-zA-Z0-9_.-]{4,40}$/',$user))$error='Kullanıcı adı 4–40 karakter olmalı; harf, rakam, nokta, tire ve alt çizgi kullanın.';
   elseif(strlen($pass)<12)$error='Şifre en az 12 karakter olmalı.';
   elseif($pass!==$pass2)$error='Şifreler eşleşmiyor.';
   else{$st=$pdo->prepare('INSERT INTO admins(username,password_hash) VALUES(?,?)');$st->execute([$user,password_hash($pass,PASSWORD_DEFAULT)]);$installed=true;$notice='Yönetici hesabı oluşturuldu. Şimdi giriş yapabilirsiniz.';}
  }
 } elseif($action==='login'){
  csrf_check();$user=trim((string)($_POST['username']??''));$pass=(string)($_POST['password']??'');
  $st=$pdo->prepare('SELECT * FROM admins WHERE username=?');$st->execute([$user]);$admin=$st->fetch();
  if($admin&&password_verify($pass,$admin['password_hash'])){session_regenerate_id(true);$_SESSION['admin_id']=(int)$admin['id'];$_SESSION['admin_username']=$admin['username'];header('Location: admin.php');exit;}else{$error='Kullanıcı adı veya şifre hatalı.';}
 }
}
if(admin_logged_in() && $_SERVER['REQUEST_METHOD']==='POST'){
 csrf_check();$action=(string)($_POST['action']??'');
 if($action==='save_service'){
  $id=(int)($_POST['id']??0);$name=trim((string)($_POST['name']??''));$cat=trim((string)($_POST['category']??''));$desc=trim((string)($_POST['description']??''));$price=(float)str_replace(',','.',(string)($_POST['price']??'0'));$icon=(string)($_POST['icon']??'web');$active=isset($_POST['active'])?1:0;$sort=(int)($_POST['sort_order']??0);
  if($name===''||$cat===''||$price<0||mb_strlen($name)>180||mb_strlen($desc)>1500){$error='Hizmet alanlarını kontrol edin.';}
  else{if($id){$st=$pdo->prepare('UPDATE services SET name=?,category=?,description=?,price=?,icon=?,active=?,sort_order=? WHERE id=?');$st->execute([$name,$cat,$desc,$price,$icon,$active,$sort,$id]);}else{$st=$pdo->prepare('INSERT INTO services(name,category,description,price,icon,active,sort_order) VALUES(?,?,?,?,?,?,?)');$st->execute([$name,$cat,$desc,$price,$icon,$active,$sort]);}$notice='Hizmet kaydedildi.';}
 }elseif($action==='delete_service'){
  $id=(int)($_POST['id']??0);$st=$pdo->prepare('DELETE FROM services WHERE id=?');$st->execute([$id]);$notice='Hizmet silindi.';
 }elseif($action==='update_order'){
  $id=(int)($_POST['id']??0);$status=(string)($_POST['status']??'Yeni');$allowed=['Yeni','Görüşülüyor','Teklif gönderildi','Onaylandı','Yapım aşamasında','Tamamlandı','İptal'];
  if(in_array($status,$allowed,true)){$st=$pdo->prepare('UPDATE orders SET status=?,updated_at=CURRENT_TIMESTAMP WHERE id=?');$st->execute([$status,$id]);$notice='Sipariş durumu güncellendi.';}
 }elseif($action==='delete_order'){
  $st=$pdo->prepare('DELETE FROM orders WHERE id=?');$st->execute([(int)($_POST['id']??0)]);$notice='Talep silindi.';
 }elseif($action==='save_settings'){
  $settings=['site_title'=>trim((string)($_POST['site_title']??'')),'meta_description'=>trim((string)($_POST['meta_description']??'')),'whatsapp'=>preg_replace('/\D+/','',(string)($_POST['whatsapp']??'')),'business_email'=>trim((string)($_POST['business_email']??''))];
  if($settings['business_email']!==''&&!filter_var($settings['business_email'],FILTER_VALIDATE_EMAIL))$error='E-posta adresini kontrol edin.';
  else{$st=$pdo->prepare('INSERT INTO settings(key,value) VALUES(?,?) ON CONFLICT(key) DO UPDATE SET value=excluded.value');foreach($settings as $k=>$v)$st->execute([$k,$v]);$notice='Site ayarları kaydedildi.';}
 }elseif($action==='change_password'){
  $old=(string)($_POST['old_password']??'');$new=(string)($_POST['new_password']??'');$again=(string)($_POST['new_password2']??'');
  $st=$pdo->prepare('SELECT password_hash FROM admins WHERE id=?');$st->execute([$_SESSION['admin_id']]);$row=$st->fetch();
  if(!$row||!password_verify($old,$row['password_hash']))$error='Mevcut şifre hatalı.';
  elseif(strlen($new)<12)$error='Yeni şifre en az 12 karakter olmalı.';
  elseif($new!==$again)$error='Yeni şifreler eşleşmiyor.';
  else{$st=$pdo->prepare('UPDATE admins SET password_hash=? WHERE id=?');$st->execute([password_hash($new,PASSWORD_DEFAULT),$_SESSION['admin_id']]);$notice='Şifreniz güncellendi.';}
 }
}
$settings=site_settings();$services=$pdo->query('SELECT * FROM services ORDER BY sort_order,id')->fetchAll();$orders=$pdo->query('SELECT * FROM orders ORDER BY id DESC LIMIT 300')->fetchAll();
$total=(int)$pdo->query('SELECT COUNT(*) FROM orders')->fetchColumn();$new=(int)$pdo->query("SELECT COUNT(*) FROM orders WHERE status='Yeni'")->fetchColumn();$done=(int)$pdo->query("SELECT COUNT(*) FROM orders WHERE status='Tamamlandı'")->fetchColumn();
