function status_slug(string $s): string { $map=['Yeni'=>'new','Görüşülüyor'=>'talking','Teklif gönderildi'=>'offer','Onaylandı'=>'approved','Yapım aşamasında'=>'progress','Tamamlandı'=>'done','İptal'=>'cancel'];return $map[$s]??'new';}
